};

function addBg(slide) {
  slide.background = { color: C.cream };
  slide.addShape(pptxgen.ShapeType.rect, { x: 0, y: 0, w: 10, h: 5.625, fill: { color: C.cream }, line: { color: C.cream } });
}

function addHeader(slide, title, kicker, slideNo) {
  slide.addText(kicker || 'GLOBAL CARBON BUDGET 2025 · FOSSIL FUELS & INDUSTRY', {
    x: 0.45, y: 0.22, w: 7.5, h: 0.22, fontFace: 'Arial', fontSize: 7.5, bold: true,
    color: C.teal, charSpace: 0.7, margin: 0,
  });
  slide.addText(title, {
    x: 0.45, y: 0.48, w: 8.55, h: 0.55, fontFace: 'Arial', fontSize: 22, bold: true,
    color: C.navy, margin: 0, breakLine: false, fit: 'shrink',
  });
  slide.addShape(pptxgen.ShapeType.line, { x: 0.45, y: 1.1, w: 9.1, h: 0, line: { color: C.line, width: 1 } });
  if (slideNo) addPage(slide, slideNo);
}

function addPage(slide, no) {
  slide.addShape(pptxgen.ShapeType.roundRect, { x: 9.27, y: 5.08, w: 0.34, h: 0.22, rectRadius: 0.04, fill: { color: C.navy, transparency: 8 }, line: { color: C.navy, transparency: 100 } });
  slide.addText(String(no).padStart(2, '0'), { x: 9.29, y: 5.105, w: 0.3, h: 0.13, fontSize: 6.5, bold: true, color: C.white, align: 'center', margin: 0 });
}

function addSource(slide, text = 'Source: Global Carbon Budget 2025 via Our World in Data') {
  slide.addText(text, { x: 0.45, y: 5.18, w: 7.8, h: 0.18, fontFace: 'Arial', fontSize: 6.8, color: C.muted, margin: 0 });
}

function addCallout(slide, text, x, y, w, h, color = C.teal) {
  slide.addShape(pptxgen.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.08, fill: { color, transparency: 8 }, line: { color, transparency: 100 } });
  slide.addText(text, { x: x + 0.12, y: y + 0.08, w: w - 0.24, h: h - 0.16, fontFace: 'Arial', fontSize: 10, bold: true, color: C.white, margin: 0.02, breakLine: false, fit: 'shrink' });
}

function addMetric(slide, value, label, x, y, w, color = C.teal) {
  slide.addText(value, { x, y, w, h: 0.36, fontFace: 'Arial', fontSize: 22, bold: true, color, margin: 0, fit: 'shrink' });
  slide.addText(label, { x, y: y + 0.39, w, h: 0.31, fontFace: 'Arial', fontSize: 8.5, color: C.ink, margin: 0, fit: 'shrink' });
}

function addBullet(slide, text, x, y, w, color = C.ink) {
  slide.addShape(pptxgen.ShapeType.ellipse, { x, y: y + 0.055, w: 0.08, h: 0.08, fill: { color: C.teal }, line: { color: C.teal } });
  slide.addText(text, { x: x + 0.16, y, w, h: 0.28, fontFace: 'Arial', fontSize: 10.8, color, margin: 0, fit: 'shrink' });
}

function axis(slide, x, y, w, h, yLabel, xLabels = []) {
  slide.addShape(pptxgen.ShapeType.line, { x, y: y + h, w, h: 0, line: { color: C.ink, width: 0.9 } });
  slide.addShape(pptxgen.ShapeType.line, { x, y, w: 0, h, line: { color: C.ink, width: 0.9 } });
  for (let i = 0; i < 4; i++) {
