  if (yLabel) slide.addText(yLabel, { x: x - 0.26, y: y - 0.15, w: 1.2, h: 0.18, fontSize: 6.8, color: C.muted, margin: 0, rotate: 270 });
  xLabels.forEach(({ text, px }) => slide.addText(text, { x: x + px * w - 0.2, y: y + h + 0.1, w: 0.55, h: 0.15, fontSize: 6.8, color: C.muted, margin: 0, align: 'center' }));
}

function addLine(slide, pts, color, width = 2.5) {
  for (let i = 0; i < pts.length - 1; i++) {
    slide.addShape(pptxgen.ShapeType.line, { x: pts[i][0], y: pts[i][1], w: pts[i+1][0] - pts[i][0], h: pts[i+1][1] - pts[i][1], line: { color, width, beginArrowType: 'none', endArrowType: 'none' } });
  }
}

function addBar(slide, label, valueLabel, ratio, x, y, w, h, color, labelW = 1.75) {
  slide.addText(label, { x, y: y + 0.02, w: labelW, h, fontFace: 'Arial', fontSize: 9.2, color: C.ink, margin: 0, fit: 'shrink' });
  slide.addShape(pptxgen.ShapeType.roundRect, { x: x + labelW + 0.08, y, w, h, rectRadius: 0.04, fill: { color: 'EAEFF4' }, line: { color: 'EAEFF4' } });
  slide.addShape(pptxgen.ShapeType.roundRect, { x: x + labelW + 0.08, y, w: Math.max(0.03, w * ratio), h, rectRadius: 0.04, fill: { color }, line: { color } });
