}

function addPlaceholderChart(slide, x, y, w, h, title, desc) {
  slide.addShape(pptxgen.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.1, fill: { color: C.white }, line: { color: C.line, width: 1 } });
  slide.addText(title, { x: x + 0.18, y: y + 0.16, w: w - 0.36, h: 0.25, fontFace: 'Arial', fontSize: 10, bold: true, color: C.navy, margin: 0 });
  slide.addText(desc, { x: x + 0.18, y: y + 0.48, w: w - 0.36, h: 0.46, fontFace: 'Arial', fontSize: 8.4, color: C.muted, margin: 0, fit: 'shrink' });
}

module.exports = { C, addBg, addHeader, addPage, addSource, addCallout, addMetric, addBullet, axis, addLine, addBar, addPlaceholderChart };
